import{_ as t,H as i,f as a,i as s}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"09｜建筑和场景摄影","description":"","frontmatter":{},"headers":[{"level":2,"title":"海边","slug":"海边","link":"#海边","children":[]},{"level":2,"title":"东京铁塔","slug":"东京铁塔","link":"#东京铁塔","children":[]},{"level":2,"title":"上海外滩","slug":"上海外滩","link":"#上海外滩","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"作业","slug":"作业","link":"#作业","children":[]}],"relativePath":"手机摄影/09｜建筑和场景摄影.md","filePath":"手机摄影/09｜建筑和场景摄影.md","lastUpdated":1779820138000}'),n={name:"手机摄影/09｜建筑和场景摄影.md"};function b(o,e,r,g,p,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_09-建筑和场景摄影" tabindex="-1">09｜建筑和场景摄影 <a class="header-anchor" href="#_09-建筑和场景摄影" aria-label="Permalink to &quot;09｜建筑和场景摄影&quot;">​</a></h1><p>你好，我是随你们去。在学习完手机摄影的前期部分和后期部分后，恭喜你，现在你已经可以大胆拿出手机去拍摄任何你希望记录的题材了。</p><p>在接下来的三节课里，除了以视频的方式带你实操外，我想再额外和你分享一些我个人拍摄照片过程中的想法。这些想法无关对错，只是始终奉行同一个原则：如何清晰表达出我想表达的内容。</p><p>这节课首先想和你分享一下我在拍摄建筑和场景时的一些想法。</p><h2 id="海边" tabindex="-1">海边 <a class="header-anchor" href="#海边" aria-label="Permalink to &quot;海边&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/834c61b9409b5c3f42589b9ebd795fbf.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/834c61b9409b5c3f42589b9ebd795fbf.jpg" alt=""></a></p><p>这是在厦门的一个海边，我当时在沙滩上休息，准备拍摄一下这个场景。我起初拍摄照片时，只拍摄了沙滩上的这一群人，你可以看到他们正在准备爬上石头。</p><p>目前这张照片里的人物状态并不好，就好像你要给一群人拍摄毕业照，大家都还没到位一样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/fae3f4a702f663ea42ec98935d50d74a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/fae3f4a702f663ea42ec98935d50d74a.jpg" alt=""></a></p><p>我在等待这群人坐好的期间，发现左右两边也有主体可以拍摄进来，索性就将他们都拍进了画面里。在拍摄的瞬间，我并没太想清楚他们之间的关系，你目前可以看到这张照片是三部分主体之间的关系。</p><p>这样一来，我们其实可以有三种选择。一种是三部分主体都保留，一种是只保留左边两部分主体，还有一种是保留右边两部分主体。</p><p>针对这三种选择，我们一一来看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/76e73058c7c5fba88ea0a6a4912a15f0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/76e73058c7c5fba88ea0a6a4912a15f0.jpg" alt=""></a></p><p>在保留三部分主体的时候，左右两边两个人与中间这群人形成了一个对比。但也正是由于三部分主体之间的对比，使得照片的信息量有些过载，对比不强烈，难以体现一个明确的主题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/ff36220d9538yy44000ed41fb0e5eefb.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/ff36220d9538yy44000ed41fb0e5eefb.jpg" alt=""></a></p><p>在保留左边两部分主体的时候，一个人和一瓶水，与一群人之间的两部分对比。他们都坐在石头上，中间隔着一块石头，这些是这张图比较有意思的看点和巧合。整体来看，这张照片的对比更强烈，主题和情绪相对也更明显一些。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/984884e00b72f4a15845eeb387f2520b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/984884e00b72f4a15845eeb387f2520b.jpg" alt=""></a></p><p>在保留右边两部分主体的时候，相对刚才左边两部分主体的照片来看，除了一个人和一群人的对比之外，由于缺失了石头、坐姿等共同点，整体信息看起来就没有左边两部分主体时候主题明确。当然，在这两张照片之间，你可以有你的理解，也许你更喜欢这张照片（人物站立和一群人坐着的对比）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/946ceeb2fa27f1f686798d198c55cb91.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/946ceeb2fa27f1f686798d198c55cb91.jpg" alt=""></a></p><p>经过以上的分析思考，我最终的选择是保留左边两部分主体。在拍摄时我也正好有单独拍摄左边两部分主体。这张相比之前那张来说，拍摄时间差在一分钟内，但是距离会稍微近一些，加上构图角度原因，处理后的画质会更好，所以接下来的调整我就基于这张照片进行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/8yy54aa7c02b8yy50eeff44331a7d1d4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/8yy54aa7c02b8yy50eeff44331a7d1d4.jpg" alt=""></a></p><p>接下来的后期工作则是把我所说的内容去进一步表达出来。由于原图色彩并不出众而主体内容又偏小，我用黑白色调来淡化色彩对于照片内容的影响。同时，黑白色调也比较适合我想要表达的情绪。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/d579a04f4d24bc3e1842f40e7b84465a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/d579a04f4d24bc3e1842f40e7b84465a.jpg" alt=""></a></p><p>在最后一步里，我对照片进行了二次构图，减少沙滩在画面的占比。这样一来沙滩和海面的占比几乎是一样的，除去天空这一部分不看的话，你会发现两部分主体基本处于水平居中的位置。</p><p>从现在的画面结构里我们可以看到，天空属于留白的一部分，然后是沙滩、海面、人物。沙滩与海面对称，人物与人物对称，底部这块的构图非常规整，这对于画面所需要的平静情绪有所帮助。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/9ba3ab49fb4927673e62c5712eyy072b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/9ba3ab49fb4927673e62c5712eyy072b.jpg" alt=""></a></p><p>我在对外分享这张照片时，由于它在全屏观看时的体验会更好，考虑到观看者几乎都是使用的手机设备，我会故意旋转角度，去引导观看者全屏观看。</p><h2 id="东京铁塔" tabindex="-1">东京铁塔 <a class="header-anchor" href="#东京铁塔" aria-label="Permalink to &quot;东京铁塔&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/a6dded284ce33b44aecb612643yy9184.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/a6dded284ce33b44aecb612643yy9184.jpg" alt=""></a></p><p>这是我走到东京铁塔下后拍摄的第一张照片。由于东京铁塔是一个非常经典的景点，关于它的照片数量巨大，如果你在拍摄这类场景时希望照片能够给别人留下印象，实际上是非常难的。</p><p>当时我希望拍摄一张属于我自己角度的东京铁塔，而不是复制人家的照片。这张例图利用前景来使得画面看起来不过于常规，拍摄起初我也挺喜欢这张照片的，不过由于才刚到塔下，我决定继续走走看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/6b03dc30b68ac01662126618d7025519.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/6b03dc30b68ac01662126618d7025519.jpg" alt=""></a></p><p>这张图的角度可以让我们看到东京铁塔不一样的一面。在某些方面来说，它也许是有趣的，但这并不是我想寻找拍摄的角度，我希望可以得到一张一眼就能知道这是东京铁塔的照片，毕竟我是第一次到这里旅游。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/413d67e00ee5b2fe178f3ae170431e27.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/413d67e00ee5b2fe178f3ae170431e27.jpg" alt=""></a></p><p>我继续走着，打算围绕着东京铁塔走一圈试试。这张照片是走到东京铁塔背后时，抱着试一试心态拍摄的。照片虽然干净，但整体看起来比较常规单调，我尝试拍摄后发现这张照片还不如第一张照片有趣。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/f874c95ca2001fb8735e8bb76bd1bbe9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/f874c95ca2001fb8735e8bb76bd1bbe9.jpg" alt=""></a></p><p>接着走到一个巷子里时，我拍摄了这张照片。这个角度并不常见，我个人还是蛮喜欢的，但是照片并没有将东京铁塔作为主体来拍摄。你可以感受到，整张照片更适合作为背景来使用，我认为目前在街道上缺少一个主体，例如路过的人物之类的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/3a805fe803dea95159b193d805d3e04c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/3a805fe803dea95159b193d805d3e04c.jpg" alt=""></a></p><p>在即将围绕东京铁塔走完一圈的时候，我遇见了这个前景为树木的场景。在那一刻，我知道这是我一直想要的场景。相比之前的所有场景，这个场景我最喜欢。东京铁塔是主体，前景也比较好看，唯一遗憾是时间已经比较晚了，拍出来的照片缺失天际的蓝色，画质也会受影响。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/b50c29a9d71915bd04db43b8d0c6e028.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/b50c29a9d71915bd04db43b8d0c6e028.jpg" alt=""></a></p><p>在后期时，我重新调整了建筑在画面中的占比，同时去掉前景左右两边较大的枝干，避免主次不清的问题。色调上我保留了天际的冷色和建筑的暖色，形成一个简单的冷暖对比。</p><h2 id="上海外滩" tabindex="-1">上海外滩 <a class="header-anchor" href="#上海外滩" aria-label="Permalink to &quot;上海外滩&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/718c1c2e9057f7641ab07866e1be6842.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/718c1c2e9057f7641ab07866e1be6842.jpg" alt=""></a></p><p>上海外滩同东京铁塔一样，也是一个非常经典的景点。关于例图角度的外滩照片，我们见得太多了，它最大的问题也是因为太常见了。在每个人都知道的地点、角度，如果你用最简单的方式拍摄，除了对于拍摄者自己，这张照片很难有独特的意义。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/a5848ebb0e5d9be9bb46fd60023871f7.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/a5848ebb0e5d9be9bb46fd60023871f7.jpg" alt=""></a></p><p>傍晚在上海外滩游走时，我被这个角度的场景吸引了。它不是我印象里最常见的那个外滩。我一路边走边拍，拍了不少角度类似但细节不同的照片。你可以注意到除了角度之外，拍摄的时间也很恰当，这是天气比较好的一天，傍晚夜幕时分，建筑灯光也都亮起。</p><p>不过，这张照片的外滩建筑成了远处背景，近处占据大面积的内容是楼梯与围栏，整体看起来有些杂乱，这并非我想要的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/903f0a0f53c74168ba6156c128bcfff4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/903f0a0f53c74168ba6156c128bcfff4.jpg" alt=""></a></p><p>对于刚才的照片，为了处理它看起来比较杂乱的问题，我尝试进行裁剪，仅保留画面中间偏右边的部分。但此时又有问题出现了。由于是弱光环境拍摄，裁剪幅度又过大，得到的照片画质很差。并且这样裁剪下来，左边部分楼梯细节看起来依旧杂乱。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/d8fbb8f17a2e8bcb1ef3ec27427c37ed.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/d8fbb8f17a2e8bcb1ef3ec27427c37ed.jpg" alt=""></a></p><p>最终我挑选了这张照片来使用。这张是我继续往前走一些后拍摄的。由于位置和角度变化，图里没能拍下黄浦江，这点还是有些遗憾。不过人群、外滩建筑、蓝色天空等这些我所需要的内容，都拍摄了下来。照片整体比较干净，不用大幅度裁剪，画质也有一定保障。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/b88249fd6542cc9c616217d2dd33f521.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%9C%BA%E6%91%84%E5%BD%B1/images/304535/b88249fd6542cc9c616217d2dd33f521.jpg" alt=""></a></p><p>在后期调整时，由于地面信息有些空白多余，我裁剪去掉了底部的信息。整个画面从地面、人物、建筑、天空四部分转为人物、建筑、天空三部分。由于本身拍摄时色彩就比较好，这张图在后期时调色倾向的选择就很多了，我这里基本是最简单的一个调色。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>根据以上例子，你可能也发现了，在拍摄场景里，由于场景永远是固定的，我们就需要通过观察和不断移动，去找出自己心里最想要拍摄的角度，又或者是耐心等待人物进入场景等等。面对同一个场景，每个人所想表达的内容都可能会不同。无论你想拍摄的是什么，通常来说，很难一次尝试就能找到最优解。</p><p>在海边的例子里，我等待人群移动到最佳位置，观察了整个场景，拍摄并分析每种选择的利弊，最终利用黑白色调来表达我所想要的情绪氛围。</p><p>在东京铁塔的例子里，我围着东京铁塔走了整整一圈。由于我是第一次去那里，也不知道周围会有什么，但是抱着试一试的心态，最终还是很幸运地找到了我喜欢的角度，并合理利用前景来拍摄出耐看的照片。</p><p>在外滩的例子里，我通过观察和移动，最终如愿得到一张内容满意，画质也没有太受影响的照片。</p><p>在场景里移动和观察是我最推崇的拍摄习惯，而不是在网上找到攻略，导航去到指定地点，固定角度拍摄一张像是复制出来的照片。无论你更喜欢哪种方式，我都希望这些经验和例子可以帮助到你，希望你在接下来的建筑场景拍摄中，能够拍出自己更满意的照片。</p><h2 id="作业" tabindex="-1">作业 <a class="header-anchor" href="#作业" aria-label="Permalink to &quot;作业&quot;">​</a></h2><p>好了，这节课到这里也就结束了。希望你根据我们这节课所讲的内容，去尽可能多地拍摄生活中遇见的场景。并点击 <a href="time://hordeChannelDetail?channelId=29" target="_blank" rel="noreferrer"><strong>这里</strong></a> ，进入部落，分享一张你认为最满意的照片。</p>',61)])])}const B=t(n,[["render",b]]);export{l as __pageData,B as default};
